INSERT INTO cards VALUES ('AS', 'A♠', 'Spades', '♠', 'Watch', 'A', 1, 'The Blip', 'One reading is not a trend: a count can drop to zero and come back.', 'The Blip', 'React to every blip and you chase ghosts; ignore them all and you miss the real outage.', 'Treat a single odd reading as a question, not an answer.', 'The Lake read empty 38 times. All 29 rechecked readings found the data still there.', 'Record', 'Check', 'Blip: as an event, needs no answer');
INSERT INTO cards VALUES ('2S', '2♠', 'Spades', '♠', 'Watch', '2', 2, 'First Poll', 'The first look records everything as observed: that is the baseline.', 'First Poll', 'A baseline taken on a bad day makes every later day look like recovery.', 'Log the whole state once before logging changes.', 'The first poll wrote 19 observed events and a whole chain.', 'Record', 'Check', '');
INSERT INTO cards VALUES ('3S', '3♠', 'Spades', '♠', 'Watch', '3', 3, 'The Interval', 'Poll as fast as the thing changes, no faster.', 'The Interval', 'Short intervals cost calls and noise; long ones miss short outages.', 'Pick the cadence from the system, then keep it steady.', 'Five-minute polls, with a ten-minute burst at one-minute polls when the owner asked.', 'Record', 'Check', '');
INSERT INTO cards VALUES ('4S', '4♠', 'Spades', '♠', 'Watch', '4', 4, 'Read-Only Probe', 'The watcher never writes to what it watches.', 'Read-Only Probe', 'Read-only probes can''t fix anything; they can only report.', 'Separate the eyes from the hands.', 'Every probe was a list, an info or a SELECT.', 'Record', 'Check', '');
INSERT INTO cards VALUES ('5S', '5♠', 'Spades', '♠', 'Watch', '5', 5, 'Balance Probe', 'One stage''s count minus the next stage''s count is the work stuck between them.', 'Balance Probe', 'A balance can be off for good reasons (pre-ledger objects), so it needs a known baseline.', 'Watch the handoffs, not just the totals.', 'The owner asked: "the inter task logic please watch".', 'Record', 'Check', '');
INSERT INTO cards VALUES ('6S', '6♠', 'Spades', '♠', 'Watch', '6', 6, 'Separate Sink', 'Watch data goes to its own store, never into the watched one.', 'Separate Sink', 'A second store is one more thing to keep, but it can''t trigger or distort the pipeline.', 'Never let the measurement become part of the thing measured.', 'Writing into the Lake''s ingest folders would have fired ingestion and changed the counts.', 'Record', 'Check', '');
INSERT INTO cards VALUES ('7S', '7♠', 'Spades', '♠', 'Watch', '7', 7, 'Threshold of Three', 'Flag only after three polls in a row.', 'Threshold of Three', 'Higher thresholds miss short real outages; lower ones cry wolf.', 'Count consecutive readings before you raise a flag.', 'Every Lake blip lasted one poll, so no flag fired.', 'Record', 'Check', '');
INSERT INTO cards VALUES ('8S', '8♠', 'Spades', '♠', 'Watch', '8', 8, 'The Unaccounted Eight', 'A finding is not an explanation.', 'The Unaccounted Eight', 'Leaving a finding open is honest but leaves work undone.', 'Record the number, say it is unexplained, and ask before investigating.', 'Eight objects sat in the Lake with no ledger row. Recorded, not yet explained.', 'Record', 'Check', '');
INSERT INTO cards VALUES ('9S', '9♠', 'Spades', '♠', 'Watch', '9', 9, 'The Hourly Round', 'Watch in rounds: twelve polls, then load.', 'The Hourly Round', 'Rounds batch the writes, but a crash mid-round leaves events unloaded.', 'End every round with a load and a read-back.', 'When the watch closed at night, the last eight events were loaded by hand: 342 on both sides.', 'Record', 'Check', '');
INSERT INTO cards VALUES ('10S', '10♠', 'Spades', '♠', 'Watch', '10', 10, 'Filtered Monitor', 'Silence the noise, never the record.', 'Filtered Monitor', 'A filter can hide a new pattern that looks like the old one.', 'Filter what you''re told about, but keep every event in the chain.', 'The known Lake flap was filtered from alerts; all of it stayed in the event log.', 'Record', 'Check', '');
INSERT INTO cards VALUES ('JS', 'J♠', 'Spades', '♠', 'Watch', 'J', 11, 'Stall Alarm', 'Silence is not success.', 'Stall Alarm', 'An alarm on silence fires when the watcher is merely slow.', 'Watch the watcher: alarm if it stops polling.', 'Twelve minutes without a poll would sound the alarm. It never sounded.', 'Record', 'Check', '');
INSERT INTO cards VALUES ('QS', 'Q♠', 'Spades', '♠', 'Watch', 'Q', 12, 'Two Runs, One Chain', 'Never run two watchers on one chain.', 'Two Runs, One Chain', 'One watcher is a single point of failure; two fork the record.', 'Stop one run before starting the next.', 'The five-minute run was stopped before the one-minute burst began.', 'Record', 'Check', 'Read-back: recover one Unaccounted card');
INSERT INTO cards VALUES ('KS', 'K♠', 'Spades', '♠', 'Watch', 'K', 13, 'The Watchtower', 'Something has to stay awake.', 'The Watchtower', 'A tower that never sleeps costs attention all night.', 'Give watching its own place, its own log and its own name.', 'The owner asked: "we need a memalloc watch tower".', 'Record', 'Check', 'Head of the Chain: answers any event');
INSERT INTO cards VALUES ('AH', 'A♥', 'Hearts', '♥', 'Check', 'A', 1, 'Readable', 'When the count says empty, fetch the newest thing by name.', 'Readable', 'A readable object proves that object, not every object.', 'Answer a scary number with a direct look.', 'Every recheck came back readable: a stats drop, not lost data.', 'Watch', 'Load', 'Blip: as an event, needs no answer');
INSERT INTO cards VALUES ('2H', '2♥', 'Hearts', '♥', 'Check', '2', 2, 'Missing', 'The other answer: the key does not exist. That is a real outage.', 'Missing', 'A check that has never said ''missing'' has never been proven to.', 'Know what failure looks like before you need to see it.', 'Zero missing results, live. A made-up key proved the path works.', 'Watch', 'Load', '');
INSERT INTO cards VALUES ('3H', '3♥', 'Hearts', '♥', 'Check', '3', 3, 'Test the Failure', 'Break it on purpose before it breaks for real.', 'Test the Failure', 'Fake failures take time and can''t cover everything.', 'Feed the check a made-up key and watch it refuse.', 'A made-up API key got HTTP 401 and was reported as refused.', 'Watch', 'Load', '');
INSERT INTO cards VALUES ('4H', '4♥', 'Hearts', '♥', 'Check', '4', 4, 'Verify Before Claiming', 'Check each ''done'' in the same step as saying it.', 'Verify Before Claiming', 'Verification slows every claim a little.', 'Never report from memory what you can read from the record.', 'Every load was followed by a hash read-back before it was called loaded.', 'Watch', 'Load', '');
INSERT INTO cards VALUES ('5H', '5♥', 'Hearts', '♥', 'Check', '5', 5, 'Count the Real Number', 'Count from the record, not from what you happened to see.', 'Count the Real Number', 'Recounting takes a query; guessing takes nothing and costs trust.', 'When you state a count, run the count.', '''Fifth today'' was wrong. The chain said 26 that day, and the log got a correction.', 'Watch', 'Load', '');
INSERT INTO cards VALUES ('6H', '6♥', 'Hearts', '♥', 'Check', '6', 6, 'Absence Needs a Scope', 'Say what was searched and what was not.', 'Absence Needs a Scope', 'A scoped answer is longer and less satisfying than ''none''.', 'Unsearched is unknown, not clear.', 'Searches named their drives, folders and file patterns, and what they skipped.', 'Watch', 'Load', '');
INSERT INTO cards VALUES ('7H', '7♥', 'Hearts', '♥', 'Check', '7', 7, 'Twenty-Five Runs', 'A test passes when it passes twenty-five times.', 'Twenty-Five Runs', 'Repetition costs minutes; flaky tests cost days.', 'Rerun the suite until luck is ruled out.', 'Skills and stores here passed 25 of 25 runs before anyone called them done.', 'Watch', 'Load', '');
INSERT INTO cards VALUES ('8H', '8♥', 'Hearts', '♥', 'Check', '8', 8, 'Read the Whole Error', 'The last line of an error is not the error.', 'Read the Whole Error', 'Digging into logs takes time when the fix might be a retry.', 'Find the real cause before choosing the fix.', 'A loader failure printed only ''}''. The tool''s own log said: authentication error, code 10000.', 'Watch', 'Load', '');
INSERT INTO cards VALUES ('9H', '9♥', 'Hearts', '♥', 'Check', '9', 9, 'Retry Once', 'Retry only when the write is idempotent.', 'Retry Once', 'Retries hide intermittent faults if nobody records them.', 'Same key, same bytes, insert-or-ignore: then retry once, and log it.', 'The refused load went through on the retry, both copies read back.', 'Watch', 'Load', '');
INSERT INTO cards VALUES ('10H', '10♥', 'Hearts', '♥', 'Check', '10', 10, 'Don''t Retry What Blocks', 'Some checks hurt the thing they check.', 'Don''t Retry What Blocks', 'Skipping the retry leaves the data older.', 'If a read stops a service, take the older copy instead.', 'A database export pauses its queries, so the older ledger dump was used.', 'Watch', 'Load', '');
INSERT INTO cards VALUES ('JH', 'J♥', 'Hearts', '♥', 'Check', 'J', 11, 'Second Check', 'When the first number looks wrong, ask a second way.', 'Second Check', 'Every second check is another call and another thing to keep.', 'Pair each risky number with an independent look.', 'Added the day the owner said: "Yes, add it".', 'Watch', 'Load', '');
INSERT INTO cards VALUES ('QH', 'Q♥', 'Hearts', '♥', 'Check', 'Q', 12, 'Tamper Test', 'A record that can be edited is not a record.', 'Tamper Test', 'Locked tables can''t fix their own typos.', 'Try to change it. It should refuse.', 'An UPDATE on the watch table was refused by its trigger. Zero rows changed.', 'Watch', 'Load', 'Read-back: recover one Unaccounted card');
INSERT INTO cards VALUES ('KH', 'K♥', 'Hearts', '♥', 'Check', 'K', 13, 'Chain Whole', 'The chain verifies end to end, and the cloud head matches.', 'Chain Whole', 'Full verification grows with the chain.', 'Verify the whole chain, not just the newest link.', '342 events, chain whole, head matched in the cloud database.', 'Watch', 'Load', 'Head of the Chain: answers any event');
INSERT INTO cards VALUES ('AD', 'A♦', 'Diamonds', '♦', 'Load', 'A', 1, 'Nothing New', 'A load with nothing to send says so and stops.', 'Nothing New', 'Quiet loads are easy to mistake for broken ones.', 'Make ''nothing to do'' an explicit, logged result.', 'A second load right after the first reported nothing new.', 'Check', 'Record', 'Blip: as an event, needs no answer');
INSERT INTO cards VALUES ('2D', '2♦', 'Diamonds', '♦', 'Load', '2', 2, 'Object First', 'Put the object, then insert the rows that point to it.', 'Object First', 'If the rows fail, an object sits with no row until the retry.', 'Order writes so a failure leaves something you can redo.', 'The object landed before the database refused; the retry finished the pair.', 'Check', 'Record', '');
INSERT INTO cards VALUES ('3D', '3♦', 'Diamonds', '♦', 'Load', '3', 3, 'Read-Back Hash', 'Fetch what you wrote and hash it.', 'Read-Back Hash', 'Every read-back doubles the transfer.', 'Don''t trust the upload''s word; trust the hash.', 'Every object''s sha256 was read back and matched.', 'Check', 'Record', '');
INSERT INTO cards VALUES ('4D', '4♦', 'Diamonds', '♦', 'Load', '4', 4, 'Head Match', 'The newest row''s hash must equal the local head.', 'Head Match', 'A head match proves the end, not every row in the middle.', 'Compare heads after every load.', 'Each round ended with the database head matching the local chain.', 'Check', 'Record', '');
INSERT INTO cards VALUES ('5D', '5♦', 'Diamonds', '♦', 'Load', '5', 5, 'Insert or Ignore', 'Loads are idempotent: sending twice changes nothing.', 'Insert or Ignore', 'Ignoring duplicates can hide a duplicate that differs.', 'Key every row so a resend is harmless.', 'Retries never doubled a row.', 'Check', 'Record', '');
INSERT INTO cards VALUES ('6D', '6♦', 'Diamonds', '♦', 'Load', '6', 6, 'Only Whole Lines', 'Send only lines that end in a newline.', 'Only Whole Lines', 'The newest line waits a round.', 'A line still being written waits for the next load.', 'Half-written lines never reached the cloud.', 'Check', 'Record', '');
INSERT INTO cards VALUES ('7D', '7♦', 'Diamonds', '♦', 'Load', '7', 7, 'Prefix Hash', 'Hash everything up to each line to catch a rewrite of an earlier one.', 'Prefix Hash', 'One more hash per line.', 'Checking only the last line misses a change further up.', 'The offline test caught exactly that, and prefix hashes went in.', 'Check', 'Record', '');
INSERT INTO cards VALUES ('8D', '8♦', 'Diamonds', '♦', 'Load', '8', 8, 'Code Ten Thousand', 'Intermittent refusals are real; record them even when the retry works.', 'Code Ten Thousand', 'An intermittent fault is hard to report and harder to fix.', 'Log every refusal with its code and what it hit.', 'Authentication error 10000 came and went on exports and one load.', 'Check', 'Record', '');
INSERT INTO cards VALUES ('9D', '9♦', 'Diamonds', '♦', 'Load', '9', 9, 'The Last Eight', 'When the watcher stops, check what it left unloaded.', 'The Last Eight', 'Hand loads break the routine.', 'Compare local count to cloud count after every stop.', 'Events 335 to 342 were loaded by hand after the watch closed.', 'Check', 'Record', '');
INSERT INTO cards VALUES ('10D', '10♦', 'Diamonds', '♦', 'Load', '10', 10, 'Fourteen Formats', 'Every format is read back, or it doesn''t count.', 'Fourteen Formats', 'More formats, more ways to be subtly wrong.', 'Write it, read it, compare row counts and the longest value.', 'CSV through SPSS, Stata, SAS, SQLite and xlsx: all read back.', 'Check', 'Record', '');
INSERT INTO cards VALUES ('JD', 'J♦', 'Diamonds', '♦', 'Load', 'J', 11, 'Fresh Folder', 'Each export and run goes into a new folder.', 'Fresh Folder', 'Folders pile up.', 'Never reuse a run folder; keep the old ones as they were.', 'Runs one to seven all kept, each with its own manifest.', 'Check', 'Record', '');
INSERT INTO cards VALUES ('QD', 'Q♦', 'Diamonds', '♦', 'Load', 'Q', 12, 'The Manifest', 'A manifest lists every file''s hash, taken after the file is final.', 'The Manifest', 'Hashing late means holding the file open longer.', 'Hash shared files once, after they close.', 'One manifest had 17 stale hashes for a shared file. Fixed: 234 of 234 now match.', 'Check', 'Record', 'Read-back: recover one Unaccounted card');
INSERT INTO cards VALUES ('KD', 'K♦', 'Diamonds', '♦', 'Load', 'K', 13, 'Local Equals Cloud', 'The job is done when both sides hold the same thing.', 'Local Equals Cloud', 'Two copies to keep in step.', 'End every session with local count = cloud count.', '342 local, 342 in the cloud.', 'Check', 'Record', 'Head of the Chain: answers any event');
INSERT INTO cards VALUES ('AC', 'A♣', 'Clubs', '♣', 'Record', 'A', 1, 'Append Only', 'Never delete, never overwrite: add alongside.', 'Append Only', 'Stores only grow.', 'Write new files; correct with new lines.', 'Every run, log and canon entry here was added, not replaced.', 'Load', 'Watch', 'Blip: as an event, needs no answer');
INSERT INTO cards VALUES ('2C', '2♣', 'Clubs', '♣', 'Record', '2', 2, 'Genesis', 'A chain starts at sixty-four zeros.', 'Genesis', 'Starting a new chain splits history.', 'One genesis per chain, written down.', 'The canon and the watch chain each begin at all zeros.', 'Load', 'Watch', '');
INSERT INTO cards VALUES ('3C', '3♣', 'Clubs', '♣', 'Record', '3', 3, 'Prev', 'Each entry names the hash of the one before.', 'Prev', 'A broken link breaks everything after it.', 'Verify the link before adding the next.', 'The canon append refuses a fork, a break or a tampered file.', 'Load', 'Watch', '');
INSERT INTO cards VALUES ('4C', '4♣', 'Clubs', '♣', 'Record', '4', 4, 'Document Every Step', 'Missing notes count as work not done.', 'Document Every Step', 'Logging takes time from the work.', 'Write the log line as it happens, not after.', 'Seven logs, 187 lines, every one a row in the session table.', 'Load', 'Watch', '');
INSERT INTO cards VALUES ('5C', '5♣', 'Clubs', '♣', 'Record', '5', 5, 'Owner''s Words, Exactly', 'Quote the owner exactly; mark your own reading as yours.', 'Owner''s Words, Exactly', 'Exact quotes keep typos and slang.', 'Never paraphrase inside quotation marks.', '"record everything please"', 'Load', 'Watch', '');
INSERT INTO cards VALUES ('6C', '6♣', 'Clubs', '♣', 'Record', '6', 6, 'Corrections Are Appends', 'A wrong time or count is fixed with a new line.', 'Corrections Are Appends', 'The wrong line stays visible.', 'Say what was wrong, what is right, and why.', 'A hand-written time and a wrong count were both corrected this way.', 'Load', 'Watch', '');
INSERT INTO cards VALUES ('7C', '7♣', 'Clubs', '♣', 'Record', '7', 7, 'Metrics, Not Text', 'Keep sessions as numbers, never their words.', 'Metrics, Not Text', 'You lose what was said.', 'Times, sizes, counts and tool names only.', 'Over eleven thousand messages kept as metrics, with no text.', 'Load', 'Watch', '');
INSERT INTO cards VALUES ('8C', '8♣', 'Clubs', '♣', 'Record', '8', 8, 'The Lock', 'One writer at a time in the shared notes.', 'The Lock', 'Waiting for the lock delays the note.', 'Take it, write, release it, and say so.', 'Every house-notes entry here was written under the lock and released.', 'Load', 'Watch', '');
INSERT INTO cards VALUES ('9C', '9♣', 'Clubs', '♣', 'Record', '9', 9, 'Hand-Over Note', 'Leave the state where the next one can pick it up.', 'Hand-Over Note', 'Notes go stale.', 'Say what is done, what is waiting, and on whom.', 'The hand-over note grew one dated update at a time.', 'Load', 'Watch', '');
INSERT INTO cards VALUES ('10C', '10♣', 'Clubs', '♣', 'Record', '10', 10, 'Scrub Before Public', 'Nothing private leaves the house by accident.', 'Scrub Before Public', 'Scrubs strip useful detail.', 'Check for IDs, storage names, paths and secrets before anything goes public.', 'The lore entry passed its scrub with zero hits.', 'Load', 'Watch', '');
INSERT INTO cards VALUES ('JC', 'J♣', 'Clubs', '♣', 'Record', 'J', 11, 'The Lore', 'A session can become a story without losing its facts.', 'The Lore', 'Story invites embellishment.', 'Take the facts from the chain; mark the reading as yours.', 'Canon-003, The Watchtower: the Lake that kept leaving.', 'Load', 'Watch', '');
INSERT INTO cards VALUES ('QC', 'Q♣', 'Clubs', '♣', 'Record', 'Q', 12, 'Varsity Squad', 'Praise goes on the record too.', 'Varsity Squad', 'Praise can make a record vain.', 'Record it in the owner''s words and keep working.', '"varsity-squad-session" — "(thats high praise)"', 'Load', 'Watch', 'Read-back: recover one Unaccounted card');
INSERT INTO cards VALUES ('KC', 'K♣', 'Clubs', '♣', 'Record', 'K', 13, 'Head of the Chain', 'The newest entry is the one everything points back through.', 'Head of the Chain', 'The head is only as good as every link below it.', 'Know your head hash and check it often.', 'The canon head moved to The Watchtower and verified at seven entries.', 'Load', 'Watch', 'Head of the Chain: answers any event');
